import{_ as t,o as e,c as l,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"账户管理 - 联系人","description":"","frontmatter":{"title":"账户管理 - 联系人"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/contacts.md","filePath":"ops-knowledge-base/presales-support/contacts.md","lastUpdated":1788259091000}'),r={name:"ops-knowledge-base/presales-support/contacts.md"};function s(i,a,n,p,c,d){return e(),l("div",null,[...a[0]||(a[0]=[o('<h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>在平台的账户体系中，主账户拥有丰富的管理权限，其中添加子账户并设置权限的功能， 能满足企业或团队多样化的管理需求。主账户可以邀请新用户加入，灵活分配各项操作权限，既保障了账户数据的安全，又提高了管理效率和协作的便利性。</p><h2 id="二、功能入口" tabindex="-1">二、功能入口 <a class="header-anchor" href="#二、功能入口" aria-label="Permalink to &quot;二、功能入口&quot;">​</a></h2><p>主账户用户可通过 “后台右上角头像 / 账户管理 / 联系人 / ” 进入用户管理界面，进行子账户的添加、邮件设置操作。</p><h2 id="三、操作指南" tabindex="-1">三、操作指南 <a class="header-anchor" href="#三、操作指南" aria-label="Permalink to &quot;三、操作指南&quot;">​</a></h2><h3 id="一-新建联系人" tabindex="-1">（一）新建联系人 <a class="header-anchor" href="#一-新建联系人" aria-label="Permalink to &quot;（一）新建联系人&quot;">​</a></h3><ol><li><p><strong>选择联系人</strong>：在联系人管理界面，点击 “选择联系人” 下拉框，选择 “新建联系人” 选项。</p></li><li><p><strong>填写基本信息</strong>：</p><ul><li>依次填写联系人的名字、姓氏，若联系人所属公司有名称，也可在公司名称栏补充录入。</li><li>准确填写联系人的邮件地址，确保后续邮件沟通顺畅。</li><li>选择对应国家区号（如 +1），并填写准确的手机号码，便于通过电话与联系人取得联系。</li></ul></li><li><p><strong>填写地址信息</strong>：</p><ul><li>详细填写联系人的街道地址，若地址内容较多，可在 “街道地址第二行” 栏补充。</li><li>准确录入城市、省份、邮编信息，确保地址定位精准。</li><li>选择联系人所在国家，系统将根据实际情况显示对应国家选项。</li></ul></li><li><p><strong>设置邮件首选项</strong>：根据联系人需求，勾选对应的邮件接收类型，包括一般邮件、账单邮件、支持邮件、产品邮件、域名邮件等，明确联系人希望接收的邮件类别。</p></li><li><p><strong>保存修改</strong>：信息填写完毕且确认无误后，点击 “保存修改” 按钮，完成新联系人添加；若放弃操作，可点击 “取消”。</p></li></ol><h2 id="四、注意事项" tabindex="-1">四、注意事项 <a class="header-anchor" href="#四、注意事项" aria-label="Permalink to &quot;四、注意事项&quot;">​</a></h2><ol><li><strong>信息准确性</strong>：填写联系人信息时，请务必确保邮件地址等关键信息准确无误，避免因信息错误导致沟通不畅或业务对接失误。</li><li><strong>权限管理</strong>：联系人信息涉及一定的隐私内容，用户需妥善管理账户权限，防止未授权人员访问或修改联系人信息。</li><li><strong>定期维护</strong>：建议用户定期对联系人信息进行检查与更新，及时删除失效联系人信息，补充新增联系人信息，确保联系人列表的有效性与实用性。</li></ol><p>通过联系人管理功能，平台为用户构建了高效的联系人信息管理体系，助力用户在账户管理中便捷维护联系人资源，提升业务沟通与服务对接效率，优化账户使用体验。</p>',10)])])}const _=t(r,[["render",s]]);export{u as __pageData,_ as default};
